DROP FUNCTION decline_agency_invitation(uuid,integer);
CREATE FUNCTION decline_agency_invitation(target uuid,expected integer,decision_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF length(decision_reason) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'Decision reason required' USING ERRCODE='23514';END IF;UPDATE agency_invitations i SET status='declined',version=version+1,reason=decision_reason WHERE i.id=target AND i.version=expected AND i.status='pending' AND i.expires_at>now() AND EXISTS(SELECT 1 FROM profiles p WHERE p.id=actor_id() AND p.state='active' AND p.email_verified=true AND lower(p.email)=i.email);IF NOT FOUND THEN RAISE EXCEPTION 'Invitation is unavailable' USING ERRCODE='42501';END IF;END $$;
REVOKE ALL ON FUNCTION decline_agency_invitation(uuid,integer,text) FROM PUBLIC;GRANT EXECUTE ON FUNCTION decline_agency_invitation(uuid,integer,text) TO haven_app;
